import json

REQUIRED = ("id", "title", "severity", "asset")
SEVERITIES = ("critical", "high", "medium", "low")

def load(path):
    with open(path, encoding="utf-8") as f:
        items = json.load(f)
    for item in items:
        for key in REQUIRED:
            if key not in item:
                raise ValueError("missing " + key + " in " + str(item.get("id", "?")))
        if item["severity"] not in SEVERITIES:
            raise ValueError("bad severity " + item["severity"])
    return items

print(len(load("findings.json")))
try:
    load("bad.json")
except ValueError as e:
    print(e)

import json

ORDER = {"critical": 0, "high": 1, "medium": 2, "low": 3}

with open("findings.json", encoding="utf-8") as f:
    items = json.load(f)
items.sort(key=lambda i: (ORDER[i["severity"]], i["id"]))
counts = {}
for i in items:
    counts[i["severity"]] = counts.get(i["severity"], 0) + 1
summary = {"total": len(items), "by_severity": counts, "top": items[0]["id"]}
print(json.dumps(summary, sort_keys=True))
